// ── Celda 2: Setup + conexión — 100% JS, sin Python ──────────────────────────
const path = require('path');
const fs   = require('fs');
const { execSync } = require('child_process');

const NNB_DIR = path.join(
  process.env.HOME || process.env.USERPROFILE,
  'OASIS', 'aleph-scriptorium', 'VectorMachineSDK'
);

// Auto-instalar deps si faltan (umap-js, js-yaml)
const needed = ['umap-js', 'js-yaml'];
const missing = needed.filter(p => !fs.existsSync(path.join(NNB_DIR, 'node_modules', p)));
if (missing.length) {
  console.log('📦 Instalando:', missing.join(', '));
  execSync(`npm install ${missing.join(' ')}`, { cwd: NNB_DIR, stdio: 'pipe' });
  console.log('✓ Instalado');
}

// ChromaClient HTTP (server en :8000)
const { ChromaClient } = require(path.join(NNB_DIR, 'node_modules', 'chromadb'));
const client = new ChromaClient({ host: 'localhost', port: 8000, database: 'default_database' });
await client.heartbeat();

const allCols = await client.listCollections();
const getName = c => typeof c === 'string' ? c : c.name;
const cols = allCols.map(getName).filter(n => n.startsWith('mc_liria_rojipardismo_'));

console.log('✓ Chroma HTTP server activo en localhost:8000');
console.log('Colecciones mc_liria_rojipardismo_* disponibles:', cols);
console.log('umap-js:', fs.existsSync(path.join(NNB_DIR, 'node_modules', 'umap-js')) ? '✓' : '✗');
console.log('js-yaml:', fs.existsSync(path.join(NNB_DIR, 'node_modules', 'js-yaml')) ? '✓' : '✗');

// ── Celda 3: Carga de embeddings ──────────────────────────────────────────────
const COLLECTIONS = [
  'mc_liria_rojipardismo_indice',
  'mc_liria_rojipardismo_bloques',
  'mc_liria_rojipardismo_speaker',
  'mc_liria_rojipardismo_review',
  'mc_liria_rojipardismo_second_pass',
];

const LABELS = {
  'mc_liria_rojipardismo_indice': 'Índice [CF-EC]',
  'mc_liria_rojipardismo_bloques': 'Bloques [CF-EC]',
  'mc_liria_rojipardismo_speaker': 'Speaker [CF-EC]',
  'mc_liria_rojipardismo_review': 'Review [CF-EC]',
  'mc_liria_rojipardismo_second_pass': '2ª pasada [CF-EC]',
};

const rows = [];
for (const colName of COLLECTIONS) {
  const col = await client.getCollection({
    name: colName,
    embeddingFunction: { generate: async () => [] },
  });
  const result = await col.get({ include: ['embeddings', 'documents', 'metadatas'] });
  for (let i = 0; i < result.ids.length; i++) {
    rows.push({
      id:        result.ids[i],
      coleccion: LABELS[colName] ?? colName,
      col_raw:   colName,
      bloque:    result.metadatas[i]?.bloque ?? '?',
      tipo:      result.metadatas[i]?.tipo   ?? '?',
      marca:     result.metadatas[i]?.marca  ?? result.ids[i],
      texto:     (result.documents[i] ?? '').slice(0, 120) + '...',
      embedding: result.embeddings[i],
    });
  }
}

const byCol = {};
for (const r of rows) byCol[r.coleccion] = (byCol[r.coleccion] ?? 0) + 1;

console.log(`Total piezas cargadas: ${rows.length}`);
console.log('Distribución:', JSON.stringify(byCol, null, 2));

globalThis._vmRows = rows;

// ── Celda 4: UMAP 2D + 3D — umap-js (100% JS, sin Python) ────────────────────
const { UMAP } = require(path.join(NNB_DIR, 'node_modules', 'umap-js'));
const rows = globalThis._vmRows;
const embeddings = rows.map(r => r.embedding);

console.log(`Calculando UMAP para ${embeddings.length} vectores (dim=${embeddings[0].length})...`);

function cosineDistance(a, b) {
  let dot = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    na += a[i] * a[i];
    nb += b[i] * b[i];
  }
  const denom = Math.sqrt(na) * Math.sqrt(nb);
  if (!denom) return 1;
  const cosine = dot / denom;
  return 1 - Math.max(-1, Math.min(1, cosine));
}

function chooseNNeighbors(nPoints) {
  if (nPoints <= 3) return Math.max(2, nPoints - 1);
  const base = nPoints <= 10 ? 4 : Math.max(5, Math.round(Math.sqrt(nPoints)));
  return Math.max(2, Math.min(30, Math.min(base, nPoints - 1)));
}

const nNeighbors = chooseNNeighbors(embeddings.length);
const umapParams = {
  nNeighbors,
  minDist: 0.25,
  spread: 1.0,
  distanceFn: cosineDistance,
};

const umap2d = new UMAP({ nComponents: 2, ...umapParams });
const proj2d = umap2d.fit(embeddings);

const umap3d = new UMAP({ nComponents: 3, ...umapParams });
const proj3d = umap3d.fit(embeddings);

for (let i = 0; i < rows.length; i++) {
  rows[i].x  = proj2d[i][0];  rows[i].y  = proj2d[i][1];
  rows[i].x3 = proj3d[i][0];  rows[i].y3 = proj3d[i][1];  rows[i].z3 = proj3d[i][2];
}
globalThis._vmRows = rows;

console.log(`✓ UMAP 2D: ${proj2d.length} × 2`);
console.log(`✓ UMAP 3D: ${proj3d.length} × 3`);
console.log(`✓ UMAP metric: cosine · nNeighbors adaptativo=${nNeighbors}`);

// ── Celda 6: Scatter 2D — Plotly JS CDN (100% JS, sin Python) ────────────────
const rows = globalThis._vmRows;
const BG = '#07101f';

const COLOR_MAP = {
  'Índice [CF-EC]': '#d9e6f2',
  'Bloques [CF-EC]': '#b9d2ea',
  'Speaker [CF-EC]': '#8fb9dd',
  'Review [CF-EC]': '#5c96c7',
  '2ª pasada [CF-EC]': '#2f5f98',
};

const byCol = {};
for (const r of rows) {
  if (!byCol[r.coleccion]) byCol[r.coleccion] = { x: [], y: [], text: [], cd: [] };
  byCol[r.coleccion].x.push(r.x);
  byCol[r.coleccion].y.push(r.y);
  byCol[r.coleccion].text.push(r.marca);
  byCol[r.coleccion].cd.push([r.marca, r.tipo, r.bloque, r.texto]);
}

const traces2d = Object.entries(byCol).map(([col, d]) => ({
  type: 'scatter', mode: 'markers+text',
  name: col,
  x: d.x, y: d.y, text: d.text,
  textposition: 'top center',
  textfont: { size: 9, color: '#c8d8e8' },
  marker: { size: 12, opacity: 0.88, color: COLOR_MAP[col] ?? '#aaaaaa' },
  customdata: d.cd,
  hovertemplate: '<b>%{customdata[0]}</b><br>tipo: %{customdata[1]}<br>bloque: %{customdata[2]}<br><i>%{customdata[3]}</i><extra></extra>',
}));

const layout2d = {
  title: { text: 'LIRIA_ROJIPARDISMO_S01 — Embeddings 2D (UMAP)', font: { color: '#c8d8e8', size: 16 } },
  plot_bgcolor: BG, paper_bgcolor: BG, height: 680,
  font: { color: '#c8d8e8' },
  legend: { title: { text: 'Colección' }, bgcolor: '#0d1a2f', bordercolor: '#2a4a7f' },
  xaxis: { showgrid: false, zeroline: false, showticklabels: false },
  yaxis: { showgrid: false, zeroline: false, showticklabels: false },
  margin: { t: 60, b: 20, l: 20, r: 20 },
};

const id2d = `plt2d_${Math.random().toString(36).slice(2, 7)}`;
const html2d = [
  `<script src="https://cdn.plot.ly/plotly-2.35.0.min.js" charset="utf-8"></script>`,
  `<div id="${id2d}" style="width:100%;height:680px;background:${BG};"></div>`,
  `<script>Plotly.newPlot('${id2d}',${JSON.stringify(traces2d)},${JSON.stringify(layout2d)},{responsive:true,displayModeBar:true});</script>`,
].join('\n');

globalThis._vmHtml2d = html2d;
console.log(`✓ Figura 2D generada — ${rows.length} piezas, ${Object.keys(byCol).length} colecciones`);

// ── Celda 8: Scatter 3D — Plotly JS CDN (100% JS, sin Python) ────────────────
const rows = globalThis._vmRows;
const BG = '#07101f';

const COLOR_MAP = {
  'Índice [CF-EC]': '#d9e6f2',
  'Bloques [CF-EC]': '#b9d2ea',
  'Speaker [CF-EC]': '#8fb9dd',
  'Review [CF-EC]': '#5c96c7',
  '2ª pasada [CF-EC]': '#2f5f98',
};

const byCol3d = {};
for (const r of rows) {
  if (!byCol3d[r.coleccion]) byCol3d[r.coleccion] = { x: [], y: [], z: [], text: [], cd: [] };
  byCol3d[r.coleccion].x.push(r.x3);
  byCol3d[r.coleccion].y.push(r.y3);
  byCol3d[r.coleccion].z.push(r.z3);
  byCol3d[r.coleccion].text.push(r.marca);
  byCol3d[r.coleccion].cd.push([r.marca, r.tipo, r.bloque, r.texto]);
}

const traces3d = Object.entries(byCol3d).map(([col, d]) => ({
  type: 'scatter3d', mode: 'markers+text',
  name: col,
  x: d.x, y: d.y, z: d.z, text: d.text,
  textposition: 'top center',
  textfont: { size: 8, color: '#c8d8e8' },
  marker: { size: 6, opacity: 0.92, color: COLOR_MAP[col] ?? '#aaaaaa' },
  customdata: d.cd,
  hovertemplate: '<b>%{customdata[0]}</b><br>tipo: %{customdata[1]}<br>bloque: %{customdata[2]}<br><i>%{customdata[3]}</i><extra></extra>',
}));

const layout3d = {
  title: { text: 'LIRIA_ROJIPARDISMO_S01 — Embeddings 3D (UMAP)', font: { color: '#c8d8e8', size: 16 } },
  paper_bgcolor: BG, height: 720, font: { color: '#c8d8e8' },
  legend: { title: { text: 'Colección' }, bgcolor: '#0d1a2f', bordercolor: '#2a4a7f' },
  scene: {
    bgcolor: BG,
    xaxis: { showgrid: false, zeroline: false, showticklabels: false },
    yaxis: { showgrid: false, zeroline: false, showticklabels: false },
    zaxis: { showgrid: false, zeroline: false, showticklabels: false },
  },
  margin: { t: 60, b: 0, l: 0, r: 0 },
};

const id3d = `plt3d_${Math.random().toString(36).slice(2, 7)}`;
const html3d = [
  `<script src="https://cdn.plot.ly/plotly-2.35.0.min.js" charset="utf-8"></script>`,
  `<div id="${id3d}" style="width:100%;height:720px;background:${BG};"></div>`,
  `<script>Plotly.newPlot('${id3d}',${JSON.stringify(traces3d)},${JSON.stringify(layout3d)},{responsive:true,displayModeBar:true});</script>`,
].join('\n');

globalThis._vmHtml3d = html3d;
console.log(`✓ Figura 3D generada — ${rows.length} piezas, ${Object.keys(byCol3d).length} colecciones`);

// ── Celda 10: KMeans + Silhouette — 100% JS, sin Python ──────────────────────
const rows = globalThis._vmRows;
const BG = '#07101f';

function euclidean(a, b) {
  let s = 0; for (let i = 0; i < a.length; i++) s += (a[i] - b[i]) ** 2; return Math.sqrt(s);
}

function kMeans(X, k, maxIter = 300) {
  const dim = X[0].length;
  const step = Math.floor(X.length / k);
  let centroids = Array.from({ length: k }, (_, i) => [...X[i * step]]);
  let labels = new Array(X.length).fill(0);
  for (let iter = 0; iter < maxIter; iter++) {
    let changed = false;
    for (let i = 0; i < X.length; i++) {
      let best = 0, bestD = Infinity;
      for (let j = 0; j < k; j++) {
        let d = 0; for (let d2 = 0; d2 < dim; d2++) d += (X[i][d2] - centroids[j][d2]) ** 2;
        if (d < bestD) { bestD = d; best = j; }
      }
      if (labels[i] !== best) { labels[i] = best; changed = true; }
    }
    if (!changed) break;
    const sums = Array.from({ length: k }, () => new Array(dim).fill(0));
    const counts = new Array(k).fill(0);
    for (let i = 0; i < X.length; i++) {
      for (let d2 = 0; d2 < dim; d2++) sums[labels[i]][d2] += X[i][d2];
      counts[labels[i]]++;
    }
    for (let j = 0; j < k; j++) {
      if (counts[j] > 0) centroids[j] = sums[j].map(s => s / counts[j]);
    }
  }
  return labels;
}

function silhouetteScore(X, labels) {
  const n = X.length, kk = Math.max(...labels) + 1;
  let total = 0;
  for (let i = 0; i < n; i++) {
    const same = X.filter((_, j) => labels[j] === labels[i] && j !== i);
    const a = same.length ? same.reduce((s, p) => s + euclidean(X[i], p), 0) / same.length : 0;
    let b = Infinity;
    for (let c = 0; c < kk; c++) {
      if (c === labels[i]) continue;
      const other = X.filter((_, j) => labels[j] === c);
      if (other.length) { const avg = other.reduce((s, p) => s + euclidean(X[i], p), 0) / other.length; if (avg < b) b = avg; }
    }
    total += b === Infinity ? 0 : (b - a) / Math.max(a, b);
  }
  return total / n;
}

const embeddings = rows.map(r => r.embedding);
const scores = {};
for (let k = 2; k <= Math.min(5, rows.length - 1); k++) {
  const lbls = kMeans(embeddings, k);
  scores[k] = parseFloat(silhouetteScore(embeddings, lbls).toFixed(4));
}
const bestK = parseInt(Object.entries(scores).sort((a, b) => b[1] - a[1])[0][0]);
const bestLabels = kMeans(embeddings, bestK);

console.log(`Silhouette scores: ${JSON.stringify(scores)}`);
console.log(`K óptimo: ${bestK} (score=${scores[bestK]})`);

const clusterColors = ['#d9e6f2', '#b9d2ea', '#8fb9dd', '#5c96c7', '#2f5f98'];
const byCluster = {};
for (let i = 0; i < rows.length; i++) {
  const cl = String(bestLabels[i]);
  if (!byCluster[cl]) byCluster[cl] = { x: [], y: [], text: [], cd: [] };
  byCluster[cl].x.push(rows[i].x); byCluster[cl].y.push(rows[i].y);
  byCluster[cl].text.push(rows[i].marca);
  byCluster[cl].cd.push([rows[i].marca, rows[i].coleccion, rows[i].tipo, rows[i].texto]);
}

const tracesCl = Object.entries(byCluster).map(([cl, d]) => ({
  type: 'scatter', mode: 'markers+text', name: `Cluster ${cl}`,
  x: d.x, y: d.y, text: d.text, textposition: 'top center',
  textfont: { size: 9, color: '#c8d8e8' },
  marker: { size: 12, opacity: 0.85, color: clusterColors[parseInt(cl)] ?? '#aaa' },
  customdata: d.cd,
  hovertemplate: '<b>%{customdata[0]}</b><br>col: %{customdata[1]}<br><i>%{customdata[3]}</i><extra></extra>',
}));

const layoutCl = {
  title: { text: `LIRIA_ROJIPARDISMO_S01 — Clusters KMeans (k=${bestK}) sobre UMAP 2D`, font: { color: '#c8d8e8', size: 16 } },
  plot_bgcolor: BG, paper_bgcolor: BG, height: 680,
  font: { color: '#c8d8e8' },
  legend: { title: { text: 'Cluster' }, bgcolor: '#0d1a2f', bordercolor: '#2a4a7f' },
  xaxis: { showgrid: false, zeroline: false, showticklabels: false },
  yaxis: { showgrid: false, zeroline: false, showticklabels: false },
  margin: { t: 60, b: 20, l: 20, r: 20 },
};

const idCl = `pltcl_${Math.random().toString(36).slice(2, 7)}`;
const htmlCl = [
  `<script src="https://cdn.plot.ly/plotly-2.35.0.min.js" charset="utf-8"></script>`,
  `<div id="${idCl}" style="width:100%;height:680px;background:${BG};"></div>`,
  `<script>Plotly.newPlot('${idCl}',${JSON.stringify(tracesCl)},${JSON.stringify(layoutCl)},{responsive:true,displayModeBar:true});</script>`,
].join('\n');

globalThis._vmHtmlClusters = htmlCl;
globalThis._vmBestK = bestK;
console.log(`✓ KMeans listo — K=${bestK}, ${rows.length} piezas`);

// ── Celda 12: Divergencia corpus ↔ geometría — 100% JS, sin Python ───────────
const rows = globalThis._vmRows;

function cosineSim(a, b) {
  let dot = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) { dot += a[i] * b[i]; na += a[i] * a[i]; nb += b[i] * b[i]; }
  return dot / (Math.sqrt(na) * Math.sqrt(nb));
}

const embeddings = rows.map(r => r.embedding);
const n = rows.length;
const K_NEIGHBORS = 3;
const divergencias = [];

for (let i = 0; i < n; i++) {
  const sims = rows
    .map((_, j) => ({ j, sim: j === i ? -Infinity : cosineSim(embeddings[i], embeddings[j]) }))
    .sort((a, b) => b.sim - a.sim)
    .slice(0, K_NEIGHBORS);

  const vecinos = sims.map(s => rows[s.j]);
  const distMedia = parseFloat(
    (sims.reduce((acc, s) => acc + (1 - s.sim), 0) / K_NEIGHBORS).toFixed(4)
  );

  const colCounts = {};
  for (const v of vecinos) colCounts[v.col_raw] = (colCounts[v.col_raw] ?? 0) + 1;
  const [colMayoritaria, cnt] = Object.entries(colCounts).sort((a, b) => b[1] - a[1])[0];

  if (colMayoritaria !== rows[i].col_raw && cnt >= 2) {
    divergencias.push({
      marca:          rows[i].marca,
      col_asignada:   rows[i].coleccion,
      col_geometrica: colMayoritaria,
      vecinos:        vecinos.map(v => v.marca),
      dist_media:     distMedia,
    });
  }
}

if (divergencias.length) {
  console.log(`Piezas con divergencia corpus ↔ geometría (${divergencias.length}):`);
  for (const d of divergencias) {
    console.log(`\n  ${d.marca}`);
    console.log(`    Asignada:   ${d.col_asignada}`);
    console.log(`    Geometría:  ${d.col_geometrica}`);
    console.log(`    Vecinos:    ${d.vecinos.join(', ')}`);
    console.log(`    Dist media: ${d.dist_media}`);
  }
} else {
  console.log('Sin divergencias — la taxonomía del Archivero coincide con la geometría.');
}

// ── Celda 14: Query semántica (chromadb-default-embed, 100% JS) ───────────────
const { pipeline, env } = require(path.join(NNB_DIR, 'node_modules', 'chromadb-default-embed'));
env.cacheDir = path.join(NNB_DIR, '.model-cache');

const QUERY = '¿Cómo se articula el vínculo entre filosofía, democracia y rojipardismo en la conversación entre Fernández Liria y Ernesto Castro?';
const N_RESULTADOS = 3;

const pipe = await pipeline('feature-extraction', 'Xenova/all-MiniLM-L6-v2');
const qOut = await pipe([QUERY], { pooling: 'mean', normalize: true });
const qEmb = qOut.tolist()[0];

console.log(`Query: «${QUERY}»\n`);
console.log('='.repeat(70));

const COLLECTIONS = [
  'mc_liria_rojipardismo_indice',
  'mc_liria_rojipardismo_bloques',
  'mc_liria_rojipardismo_speaker',
  'mc_liria_rojipardismo_review',
  'mc_liria_rojipardismo_second_pass',
];
const LABELS = {
  'mc_liria_rojipardismo_indice': 'Índice [CF-EC]',
  'mc_liria_rojipardismo_bloques': 'Bloques [CF-EC]',
  'mc_liria_rojipardismo_speaker': 'Speaker [CF-EC]',
  'mc_liria_rojipardismo_review': 'Review [CF-EC]',
  'mc_liria_rojipardismo_second_pass': '2ª pasada [CF-EC]',
};

for (const colName of COLLECTIONS) {
  const col = await client.getCollection({
    name: colName,
    embeddingFunction: { generate: async () => [] },
  });
  const result = await col.query({
    queryEmbeddings: [qEmb],
    nResults: N_RESULTADOS,
    include: ['documents', 'metadatas', 'distances'],
  });
  const docs      = result.documents[0];
  const metas     = result.metadatas[0];
  const distances = result.distances[0];

  console.log(`\n▶ ${LABELS[colName] ?? colName}`);
  console.log('-'.repeat(50));
  for (let i = 0; i < docs.length; i++) {
    const etiqueta = metas[i]?.marca ?? metas[i]?.bloque ?? colName;
    console.log(`  [${distances[i].toFixed(3)}]  ${etiqueta}`);
    console.log(`           ${docs[i].slice(0, 120)}…`);
  }
}

// ── Celda 16: Exportar a GH Pages — 100% JS (js-yaml + fs, sin Python) ───────
const yaml = require(path.join(NNB_DIR, 'node_modules', 'js-yaml'));

const REPO_ROOT = path.join(
  process.env.HOME || process.env.USERPROFILE,
  'OASIS', 'aleph-scriptorium'
);
const EXPORT_DIR = path.join(REPO_ROOT, 'DocumentMachineSDK/docs/azul/cuadernos');
const DATA_FILE  = path.join(REPO_ROOT, 'DocumentMachineSDK/docs/_data/cuadernos_cf_ec_transc.yml');

fs.mkdirSync(EXPORT_DIR, { recursive: true });
fs.mkdirSync(path.dirname(DATA_FILE), { recursive: true });

const TODAY = new Date().toISOString().slice(0, 10);
const PREFIX = 'liria_rojipardismo';

const exports = [
  {
    id:          `${PREFIX}_2d`,
    filename:    `${PREFIX}_2d.html`,
    title:       'LIRIA_ROJIPARDISMO_S01 — Espacio 2D',
    descripcion: 'Proyección UMAP 2D. Paleta azul — mod/cf_ec_transc.',
    html:        globalThis._vmHtml2d ?? '',
  },
  {
    id:          `${PREFIX}_3d`,
    filename:    `${PREFIX}_3d.html`,
    title:       'LIRIA_ROJIPARDISMO_S01 — Espacio 3D',
    descripcion: 'Proyección UMAP 3D rotable.',
    html:        globalThis._vmHtml3d ?? '',
  },
  {
    id:          `${PREFIX}_clusters`,
    filename:    `${PREFIX}_clusters.html`,
    title:       `LIRIA_ROJIPARDISMO_S01 — Clusters semánticos (K=${globalThis._vmBestK ?? '?'})`,
    descripcion: `Agrupación K-means (K=${globalThis._vmBestK ?? '?'}).`,
    html:        globalThis._vmHtmlClusters ?? '',
  },
];

console.log('=== Exportación GH Pages ===');
for (const e of exports) {
  const dest = path.join(EXPORT_DIR, e.filename);
  const fullHtml = `<!DOCTYPE html><html><head><meta charset="UTF-8"/><title>${e.title}</title></head><body style="margin:0;background:#07101f;">${e.html}</body></html>`;
  fs.writeFileSync(dest, fullHtml, 'utf-8');
  const sizeKb = Math.round(fs.statSync(dest).size / 1024);
  console.log(`  ✓ ${e.filename.padEnd(30)} ${sizeKb} KB`);
}

// Actualizar registry YAML (incremental)
let existing = [];
if (fs.existsSync(DATA_FILE)) {
  const noComments = fs.readFileSync(DATA_FILE, 'utf-8')
    .split('\n').filter(l => !l.startsWith('#')).join('\n');
  try { existing = yaml.load(noComments) || []; } catch { existing = []; }
}

const nuevosIds = new Set(exports.map(e => e.id));
const registrosBase = existing.filter(r => !nuevosIds.has(r.id));
const registrosNuevos = exports.map(e => ({
  id:          e.id,
  title:       e.title,
  file:        'azul/cuadernos/' + e.filename,
  descripcion: e.descripcion,
  fecha:       TODAY,
  colecciones: 'Índice [CF-EC] · Bloques [CF-EC] · Speaker [CF-EC] · Review [CF-EC] · 2ª pasada [CF-EC]',
}));

const registrosFinales = [...registrosBase, ...registrosNuevos];
const header = '# Cuadernos vectoriales — mod/cf_ec_transc\n# Generado automáticamente. No editar a mano.\n\n';
fs.writeFileSync(DATA_FILE, header + yaml.dump(registrosFinales, { allowUnicode: true, sortKeys: false }), 'utf-8');

console.log(`\n  ${path.basename(DATA_FILE)} → ${registrosFinales.length} entradas totales`);
console.log(`  Destino: ${EXPORT_DIR}`);
